import sys, json, torch, importlib
sys.path.insert(0, '.')
import torch_npu

fw_mod = importlib.import_module('7_ConvStandard2d_torch')
im_mod = importlib.import_module('7_ConvStandard2d_triton_best_r0817')
Framework, Impl = fw_mod.Model, im_mod.ModelNew

with open('7_ConvStandard2d.json') as f:
    cases = [json.loads(l) for l in f if l.strip()]

# 与 get_input_groups 完全一致的数据生成逻辑
dtype_map = {"float32": torch.float32, "float16": torch.float16, "bfloat16": torch.bfloat16}

def make_inputs(idx):
    case = cases[idx]
    tensor_inputs = [i for i in case['inputs'] if i.get('type') == 'tensor']
    attrs = {i['name']: i['value'] for i in case['inputs'] if i.get('type') == 'attr'}
    x_info = tensor_inputs[0]
    dtype = dtype_map.get(x_info['dtype'], torch.float32)
    if idx % 2 == 0:
        mu = float(torch.empty(1).uniform_(-5.0, 5.0).item())
        sigma = float(torch.empty(1).uniform_(0.1, 2.0).item())
        x = torch.normal(mu, sigma, x_info['shape'], dtype=dtype)
    else:
        x = torch.empty(x_info['shape'], dtype=dtype).uniform_(-5.0, 5.0)
    return (x, attrs['in_channels'], attrs['out_channels'], attrs['kernel_size'],
            attrs.get('stride',1), attrs.get('padding',0), attrs.get('dilation',1),
            attrs.get('groups',1), attrs.get('bias',True)), attrs

torch.manual_seed(0); torch.npu.manual_seed(0)
fw = Framework().to('npu')
torch.manual_seed(0); torch.npu.manual_seed(0)
im = Impl().to('npu')

ATOL, RTOL = 1e-3, 2**-13
print(f"判定标准: |diff| <= atol + rtol*|golden|, atol={ATOL}, rtol={RTOL:.6e}")
print(f"{'case':>4} {'max_abs_diff':>14} {'violations':>10} {'pass':>5}")

for idx in [9, 19]:  # case10, case20 (0-indexed)
    inputs, attrs = make_inputs(idx)
    inputs_npu = tuple(x.to('npu') if torch.is_tensor(x) else x for x in inputs)
    with torch.no_grad():
        y_fw = fw(inputs_npu)
        y_im = im(inputs_npu)
    torch.npu.synchronize()
    diff = (y_fw - y_im).abs()
    bound = ATOL + RTOL * y_fw.abs()
    violations = (diff > bound).sum().item()
    max_abs = diff.max().item()
    total = diff.numel()
    ok = violations == 0
    print(f'{idx+1:>4} {max_abs:>14.6e} {violations:>4}/{total:<5} {"PASS" if ok else "FAIL"}')

